// Documents source: PDF, Word, Excel (.xlsx, .xls) and CSV into Document / Section / Table / Row nodes or mapped
// things with provenance; re-scan by hash (changes and removals); reset; access rules on document fields;
// sync-out; and untrusted-file guards (zip bombs, oversize files, page limits, macros, wrong types, DOCTYPE).
// Fixtures are generated by test/fixtures/make-documents.mjs (invented content).
import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, readFileSync, rmSync, utimesSync, existsSync, readdirSync, copyFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import http from 'node:http';
import { fileURLToPath } from 'node:url';
import { PGlite } from '@electric-sql/pglite';
import { readDocument } from '../src/documents/index.js';
import { DocumentsSource, columnNames, tableSignature } from '../src/sources/documents.js';
import { documentsMapping } from '../src/studio/compile.js';
import { Mapper } from '../src/mapper.js';
import { GraphStore } from '../src/graph.js';
import { PolicyStore } from '../src/abac/policy.js';
import { AbacEngine, MASK } from '../src/abac/engine.js';
import { SyncOut } from '../src/syncout/index.js';
import { startServer } from '../src/app.js';
import { fixtures, makePdf, pdfPage, makeDocx, makeWorkbook, makeZip, zipBomb, lyingZip, CUSTOMERS } from './fixtures/make-documents.mjs';

const FX = fileURLToPath(new URL('./fixtures/documents/', import.meta.url));
const tmp = () => mkdtempSync(join(tmpdir(), 'sgdocs-'));
const sigOf = header => tableSignature(columnNames(header));
const CUSTOMER_SIG = sigOf(CUSTOMERS[0]);
const folderWith = files => { const d = tmp(); for (const [n, b] of Object.entries(files)) writeFileSync(join(d, n), b); return d; };
const bump = (path, s) => utimesSync(path, new Date(Date.now() + s * 1000), new Date(Date.now() + s * 1000)); // make the change visible even on coarse clocks

// A documents source wired to a mapper and graph, kept alive between scans (like a running pipeline).
function rig(folder, tables = [], limits) {
  const s = { id: 'docs', tables };
  const src = new DocumentsSource({ folder, topic: 'docs', limits, tableTopics: Object.fromEntries(tables.map((t, i) => [t.sig, `docs__t${i + 1}`])), tableKeys: Object.fromEntries(tables.map(t => [t.sig, t.key])) }, { onError: () => {} });
  const g = new GraphStore(), m = new Mapper(documentsMapping(s));
  const scan = async () => { const evs = []; await src.poll(async ev => { evs.push(ev); await m.apply(ev, g); }); return evs; };
  return { g, scan, src };
}
const byKey = (g, label) => Object.fromEntries(g.nodes(label).map(n => [n.key, n.props]));

test('fixtures on disk match the generator', () => {
  for (const n of Object.keys(fixtures())) assert.ok(existsSync(join(FX, n)), `${n} missing: run node test/fixtures/make-documents.mjs`);
});

test('PDF: page text, a simple table, metadata and page count', async () => {
  const r = await readDocument(readFileSync(join(FX, 'invoice.pdf')), 'invoice.pdf');
  assert.equal(r.meta.title, 'Invoice 1042'); assert.equal(r.meta.author, 'Acme Parts Billing'); assert.equal(r.meta.page_count, 2);
  assert.equal(r.sections.length, 2); assert.match(r.sections[0].text, /Payment is due within 30 days/); assert.equal(r.sections[1].page, 2);
  assert.doesNotMatch(r.sections[0].text, /Hex bolt/, 'table lines are not repeated in the page text');
  assert.equal(r.tables.length, 1);
  assert.deepEqual(r.tables[0].header, ['sku', 'item', 'qty', 'price']);
  assert.deepEqual(r.tables[0].rows.map(x => x.cells), [['P-100', 'Hex bolt', '40', '0.25'], ['P-200', 'Wing nut', '25', '0.40'], ['P-300', 'Washer', '100', '0.05']]);
  assert.equal(r.tables[0].location, 'page 1');
});

test('PDF with no text layer gets an OCR note instead of failing', async () => {
  const r = await readDocument(makePdf([[]]), 'scan.pdf');
  assert.equal(r.tables.length, 0); assert.match(r.notes.join(' '), /scanned PDF.*OCR, which is not included/);
});

test('Word: sections by heading, table, core properties; outside links are never fetched', async () => {
  let hits = 0; const srv = http.createServer((q, s) => { hits++; s.end('x'); });
  await new Promise(r => srv.listen(0, '127.0.0.1', r));
  try {
    const buf = makeDocx([{ h: 'Plan' }, { p: 'First & second <steps>.' }, { table: [['id', 'what'], ['1', 'Order bolts'], ['2', 'Check nuts']] }, { h: 'Later', level: 2 }, { p: 'Review.' }],
      { title: 'Ops plan', author: 'Dee' }, { externalLink: true, linkUrl: `http://127.0.0.1:${srv.address().port}/tracker.png`, macro: true });
    const r = await readDocument(buf, 'plan.docx');
    assert.deepEqual(r.sections.map(s => [s.heading, s.level]), [['Plan', 1], ['Later', 2]]);
    assert.equal(r.sections[0].text, 'First & second <steps>.', 'entities decoded, text kept');
    assert.deepEqual(r.tables[0].header, ['id', 'what']); assert.deepEqual(r.tables[0].rows[1], { cells: ['2', 'Check nuts'], row: 2 });
    assert.equal(r.meta.title, 'Ops plan'); assert.equal(r.meta.author, 'Dee'); assert.equal(r.meta.created, '2026-01-05T09:00:00Z');
    assert.match(r.notes.join(' '), /1 link to outside files or web pages was not followed/);
    assert.match(r.notes.join(' '), /Macros in this file were ignored/);
    await new Promise(res => setTimeout(res, 100));
    assert.equal(hits, 0, 'the linked address was never requested');
  } finally { srv.close(); }
});

test('Excel .xlsx and .xls: each sheet is a table with real sheet row numbers; CSV too', async () => {
  const x = await readDocument(readFileSync(join(FX, 'customers.xlsx')), 'customers.xlsx');
  assert.deepEqual(x.tables.map(t => t.name), ['Customers', 'Regions']);
  assert.deepEqual(x.tables[0].rows[0], { cells: ['C1', 'Ada Lovelace', 'ada@example.test', 'gold'], row: 2 });
  assert.equal(x.meta.title, 'Customer list'); assert.equal(x.meta.sheet_names, 'Customers, Regions');
  const xls = await readDocument(readFileSync(join(FX, 'products.xls')), 'products.xls');
  assert.deepEqual(xls.tables[0].header, ['sku', 'name', 'price']); assert.deepEqual(xls.tables[0].rows[1], { cells: ['P-200', 'Wing nut', 0.4], row: 3 });
  const csv = await readDocument(readFileSync(join(FX, 'orders.csv')), 'orders.csv');
  assert.deepEqual(csv.tables[0].rows.map(r => r.row), [2, 3]); assert.equal(csv.tables[0].location, 'file');
});

test('graph: Document, Section, Table and Row nodes, mapped things, and provenance on every row', async () => {
  const dir = tmp(); for (const n of readdirSync(FX)) copyFileSync(join(FX, n), join(dir, n));
  const { g, scan } = rig(dir, [{ sig: CUSTOMER_SIG, entity: 'Customer', key: 'customer_id', fields: { customer_id: 'customer_id', name: 'name', email: 'email', tier: 'tier' } }]);
  await scan();
  const docs = byKey(g, 'Document');
  assert.deepEqual(Object.keys(docs).sort(), ['docs/customers.xlsx', 'docs/invoice.pdf', 'docs/orders.csv', 'docs/products.xls', 'docs/suppliers.docx']);
  const pdf = docs['docs/invoice.pdf'];
  assert.equal(pdf.file_name, 'invoice.pdf'); assert.equal(pdf.file_type, 'PDF'); assert.equal(pdf.size_bytes, readFileSync(join(dir, 'invoice.pdf')).length);
  assert.match(pdf.sha256, /^[0-9a-f]{64}$/); assert.ok(!isNaN(Date.parse(pdf.modified_at))); assert.equal(pdf.title, 'Invoice 1042'); assert.equal(pdf.page_count, 2); assert.equal(pdf.status, 'read');
  assert.equal(docs['docs/suppliers.docx'].author, 'Purchasing team');
  // mapped: customers sheet rows become Customer things with file, sheet and row
  const c = byKey(g, 'Customer');
  assert.deepEqual(Object.keys(c).sort(), ['C1', 'C2', 'C3']);
  assert.deepEqual([c.C2.source_file, c.C2.source_location, c.C2.source_row], ['customers.xlsx', 'sheet Customers', 3]);
  assert.equal(c.C2.email, 'ben@example.test');
  assert.equal(g.query('(t:Table)-[:HAS_ROW]->(c:Customer {key:"C1"})').length, 1, 'each thing links back to its table');
  // unmapped: PDF table rows are Row nodes with page and row
  const rows = g.nodes('Row').filter(r => r.props.source_file === 'invoice.pdf');
  assert.equal(rows.length, 3);
  assert.deepEqual(rows.map(r => [r.props.sku, r.props.source_location, r.props.source_row]).sort(), [['P-100', 'page 1', 1], ['P-200', 'page 1', 2], ['P-300', 'page 1', 3]]);
  for (const r of g.nodes('Row')) for (const f of ['source_file', 'source_location', 'source_row']) assert.ok(r.props[f] != null, `Row ${r.key} keeps ${f}`);
  const xlsRow = g.nodes('Row').find(r => r.props.sku === 'P-200' && r.props.source_file === 'products.xls');
  assert.deepEqual([xlsRow.props.source_location, xlsRow.props.source_row, xlsRow.props.price], ['sheet Products', 3, 0.4]);
  assert.equal(g.query('(d:Document {key:"docs/invoice.pdf"})-[:HAS_TABLE]->(t:Table)-[:HAS_ROW]->(r:Row)').length, 3);
  assert.equal(g.query('(d:Document {key:"docs/suppliers.docx"})-[:HAS_SECTION]->(s:Section)').length, 2);
  assert.equal(g.nodes('Section').find(s => s.props.source_file === 'invoice.pdf' && s.props.source_location === 'page 2')?.props.heading, 'Page 2');
});

test('re-scan: unchanged and touched-but-identical files are not re-read; changed files update their nodes by hash', async () => {
  const dir = folderWith({ 'customers.xlsx': readFileSync(join(FX, 'customers.xlsx')), 'orders.csv': readFileSync(join(FX, 'orders.csv')) });
  const { g, scan } = rig(dir, [{ sig: CUSTOMER_SIG, entity: 'Customer', key: 'customer_id', fields: { name: 'name', tier: 'tier' } }]);
  await scan();
  const sha1 = byKey(g, 'Document')['docs/customers.xlsx'].sha256;
  assert.deepEqual(await scan(), [], 'nothing changed, nothing sent');
  bump(join(dir, 'orders.csv'), 5);
  assert.deepEqual(await scan(), [], 'same content with a new time is not a change (same hash)');
  // C2 changes tier, C3 is removed, C4 is added
  writeFileSync(join(dir, 'customers.xlsx'), makeWorkbook({ Customers: [CUSTOMERS[0], CUSTOMERS[1], ['C2', 'Ben Okafor', 'ben@example.test', 'platinum'], ['C4', 'Dev Rao', 'dev@example.test', 'silver']] }));
  bump(join(dir, 'customers.xlsx'), 10);
  const evs = await scan();
  const c = byKey(g, 'Customer');
  assert.deepEqual(Object.keys(c).sort(), ['C1', 'C2', 'C4']);
  assert.equal(c.C2.tier, 'platinum'); assert.equal(c.C4.source_row, 4);
  const doc = byKey(g, 'Document')['docs/customers.xlsx'];
  assert.notEqual(doc.sha256, sha1, 'the document hash is updated'); assert.equal(doc.sheet_names, 'Customers');
  assert.equal(g.nodes('Row').filter(r => r.props.source_location === 'sheet Regions').length, 0, 'rows of a removed sheet are gone');
  assert.equal(g.nodes('Table').filter(t => t.props.source_file === 'customers.xlsx').length, 1);
  assert.ok(evs.some(e => e.op === 'u' && e.topic === 'docs__doc'));
  assert.ok(evs.every(e => !e.topic.startsWith('docs__') || !String(e.data?.doc_id || e.data?._table_id || '').includes('orders.csv')), 'the unchanged file sent nothing');
});

test('re-scan: a removed file takes its document, sections, tables, rows and things out of the graph', async () => {
  const dir = folderWith({ 'invoice.pdf': readFileSync(join(FX, 'invoice.pdf')), 'customers.xlsx': readFileSync(join(FX, 'customers.xlsx')) });
  const { g, scan } = rig(dir, [{ sig: CUSTOMER_SIG, entity: 'Customer', key: 'customer_id', fields: { name: 'name' } }]);
  await scan();
  assert.equal(g.nodes('Customer').length, 3);
  rmSync(join(dir, 'customers.xlsx'));
  await scan();
  assert.deepEqual(Object.keys(byKey(g, 'Document')), ['docs/invoice.pdf']);
  assert.equal(g.nodes('Customer').length, 0);
  assert.ok(g.nodes('Table').every(t => t.props.source_file === 'invoice.pdf'));
  assert.ok(g.nodes('Row').every(r => r.props.source_file === 'invoice.pdf'));
  assert.ok(g.edges().every(e => !e.from.includes('customers.xlsx') && !e.to.includes('customers.xlsx')), 'no edges left pointing at the removed file');
  rmSync(join(dir, 'invoice.pdf'));
  await scan();
  assert.deepEqual(g.counts(), { nodes: 0, edges: 0 });
});

test('untrusted files: zip bombs (honest and lying), oversize files, page limit, macros, wrong type and DOCTYPE are refused with clear errors', async () => {
  await assert.rejects(readDocument(zipBomb(), 'bomb.docx'), /zip bomb/);
  await assert.rejects(readDocument(lyingZip(), 'lying.docx'), /zip bomb/, 'a part bigger than its declared size is caught while unpacking');
  const xlBomb = makeZip([{ name: '[Content_Types].xml', data: '<Types/>' }, { name: 'xl/workbook.xml', data: '<workbook/>' }, { name: 'xl/worksheets/sheet1.xml', data: Buffer.alloc(9e6, 0x41), declaredSize: 2000 }]);
  await assert.rejects(readDocument(xlBomb, 'bomb.xlsx'), /zip bomb/, 'workbooks are checked before the spreadsheet reader unpacks them');
  await assert.rejects(readDocument(readFileSync(join(FX, 'customers.xlsx')), 'customers.xlsx', { zipMaxTotalBytes: 5000 }), /zip bomb.*more than/);
  await assert.rejects(readDocument(Buffer.alloc(3000, 0x20), 'big.csv', { maxFileBytes: 2000 }), /This file is 3 KB; the limit is 2 KB/);
  const threePages = makePdf([pdfPage({ title: 'One' }), pdfPage({ title: 'Two' }), pdfPage({ title: 'Three' })]);
  await assert.rejects(readDocument(threePages, 'long.pdf', { maxPages: 2 }), /This PDF has 3 pages; the limit is 2/);
  await assert.rejects(readDocument(makeDocx([{ p: 'x' }]), 'm.docm'), /Macro-enabled/);
  await assert.rejects(readDocument(Buffer.from('hello'), 'fake.pdf'), /named \.pdf but is not a PDF/);
  await assert.rejects(readDocument(Buffer.from('hello'), 'fake.docx'), /not a Word document/);
  await assert.rejects(readDocument(Buffer.from('hello'), 'fake.xls'), /not an Excel 97-2003 workbook/);
  const dtd = makeZip([{ name: 'word/document.xml', data: '<?xml version="1.0"?><!DOCTYPE x [<!ENTITY a "aaaa">]><w:document><w:body><w:p><w:r><w:t>&a;</w:t></w:r></w:p></w:body></w:document>' }]);
  await assert.rejects(readDocument(dtd, 'dtd.docx'), /document type declaration/);
  // In a folder, a bad file becomes a Document with the problem and does not stop the others.
  const dir = folderWith({ 'bomb.docx': zipBomb(), 'orders.csv': readFileSync(join(FX, 'orders.csv')), 'notes.txt': 'skipped' });
  const { g, scan } = rig(dir, [], { maxFileBytes: 1e6 });
  await scan();
  const d = byKey(g, 'Document');
  assert.deepEqual(Object.keys(d).sort(), ['docs/bomb.docx', 'docs/orders.csv']);
  assert.equal(d['docs/bomb.docx'].status, 'could not read'); assert.match(d['docs/bomb.docx'].problem, /zip bomb/);
  assert.equal(g.nodes('Row').length, 2);
  const big = folderWith({ 'big.csv': Buffer.alloc(5000, 0x41) }), r2 = rig(big, [], { maxFileBytes: 4000 });
  await r2.scan();
  assert.match(byKey(r2.g, 'Document')['docs/big.csv'].problem, /the limit is/);
});

test('access rules: document fields are hidden until reviewed; sync-out sends them masked and removes deleted files downstream', async () => {
  const dir = folderWith({ 'customers.xlsx': readFileSync(join(FX, 'customers.xlsx')) });
  const { g, scan } = rig(dir, [{ sig: CUSTOMER_SIG, entity: 'Customer', key: 'customer_id', fields: { name: 'name', email: 'email' } }]);
  await scan();
  const policy = new PolicyStore(); policy.register(g.schema());
  const engine = new AbacEngine(policy); engine.keyFields = { Document: ['doc_id', 'path'], Table: ['source_file'], Row: ['source_file'], Customer: ['customer_id'] };
  const analyst = engine.subject('analyst'), owner = engine.subject('owner');
  const doc = g.nodes('Document')[0], v = engine.viewNode(analyst, doc);
  for (const f of ['file_name', 'path', 'sha256', 'size_bytes', 'title', 'author']) assert.equal(v.props[f], MASK, `${f} is hidden from clearance 1 until reviewed`);
  assert.match(v.key, /^anon-/, 'the file path in the key is replaced with a pseudonym');
  assert.equal(engine.viewNode(owner, doc).props.file_name, 'customers.xlsx', 'clearance 3 sees unreviewed fields');
  const cust = engine.viewNode(analyst, g.nodes('Customer')[0]);
  assert.equal(cust.props.source_file, MASK, 'provenance fields follow the same rules'); assert.equal(cust.props.email, MASK);
  policy.setField('Document', 'file_name', 'low'); policy.setField('Customer', 'name', 'low');
  assert.equal(engine.viewNode(analyst, doc).props.file_name, 'customers.xlsx');
  assert.equal(engine.viewNode(analyst, doc).props.sha256, MASK);
  // sync-out to PostgreSQL (PGlite) as the sync service (clearance 1)
  const db = new PGlite(), so = new SyncOut({ graph: g, engine, checkpointFile: join(tmp(), 'cp.json'), factories: { postgres: { instance: db } } });
  await so.load(); await so.configure([{ id: 'pg', name: 'W', kind: 'postgres', settings: {}, asUser: 'sync-service' }]); await so.cycle();
  const sent = (await db.query("SELECT props FROM sg_nodes WHERE label='Document'")).rows;
  assert.equal(sent.length, 1); assert.equal(sent[0].props.file_name, 'customers.xlsx'); assert.equal(sent[0].props.author, MASK);
  assert.equal((await db.query("SELECT count(*)::int n FROM sg_nodes WHERE label='Customer'")).rows[0].n, 3);
  rmSync(join(dir, 'customers.xlsx')); await scan(); await so.cycle();
  assert.equal((await db.query('SELECT count(*)::int n FROM sg_nodes')).rows[0].n, 0, 'removing the file removes its things downstream');
  await so.stop(); await db.close();
});

// ---- Guided API: upload, scan preview with plain-language suggestions, save, Explore as another user, reset
const data = join(tmp(), 'data');
const S = await startServer({ port: 0, dataDir: data, log: null });
after(() => S.close());
const base = `http://127.0.0.1:${S.app.port}`;
const post = async (p, b, h = {}) => { const r = await fetch(base + p, { method: 'POST', headers: { 'content-type': 'application/json', ...h }, body: JSON.stringify(b) }); return { status: r.status, body: await r.json() }; };
const until = async (fn, ms = 8000) => { const t = Date.now(); while (Date.now() - t < ms) { if (await fn()) return true; await new Promise(r => setTimeout(r, 100)); } return false; };

test('wizard API: upload documents, preview tables with suggestions in plain words, save, and Explore under access rules', async () => {
  const bad = await (await fetch(`${base}/api/studio/upload?folder=w1&name=run.exe`, { method: 'POST', body: 'MZ' })).json();
  assert.match(bad.error, /Upload PDF, Word/);
  let folder;
  for (const n of ['customers.xlsx', 'invoice.pdf', 'suppliers.docx']) folder = (await (await fetch(`${base}/api/studio/upload?folder=w1&name=${n}`, { method: 'POST', body: readFileSync(join(FX, n)) })).json()).folder;
  assert.ok(folder.startsWith(join(data, 'uploads')));
  const missing = (await post('/api/studio/test', { kind: 'documents', settings: { folder: join(data, 'nope') } })).body;
  assert.equal(missing.ok, false); assert.match(missing.message, /couldn't find the folder/);
  const t = (await post('/api/studio/test', { kind: 'documents', settings: { folder } })).body;
  assert.equal(t.ok, true); assert.match(t.message, /We read 3 of 3 files .* and found 4 tables/);
  const cust = t.groups.find(g => g.sig === CUSTOMER_SIG);
  assert.equal(cust.sentence, 'The table in sheet Customers of customers.xlsx looks like a list of Customers, each identified by customer_id. Each row can become a Customer in your graph and will remember its file, sheet and row.');
  assert.equal(t.groups.find(g => g.columns.includes('supplier_id')).suggestion.entity, 'Supplier');
  assert.equal(t.groups.find(g => g.columns.includes('region')).suggestion.entity, 'Region', 'a sheet name is used when nothing else fits');
  assert.equal(cust.preview[0].source_row, 2);
  const taken = await post('/api/studio/sources', { name: 'Docs', kind: 'documents', settings: { folder }, tables: [{ sig: cust.sig, entity: 'Table', key: 'customer_id' }] });
  assert.equal(taken.status, 400); assert.match(taken.body.error, /used for the documents themselves/);
  const saved = await post('/api/studio/sources', { name: 'Docs', kind: 'documents', settings: { folder }, tables: [{ sig: cust.sig, entity: 'Customer', key: 'customer_id' }] });
  assert.equal(saved.status, 200);
  assert.ok(await until(() => S.app.graph.nodes('Customer').length === 3 && S.app.graph.nodes('Document').length === 3));
  const home = await (await fetch(`${base}/api/studio/home`)).json();
  assert.equal(home.sources[0].kind, 'documents');
  // Owner sees file names; the analyst (clearance 1) sees them hidden and can't search them, until the field is reviewed.
  const q = { question: { entity: 'Document', filters: [] } };
  const own = (await post('/api/studio/ask', q)).body;
  assert.ok(own.table.some(r => r['Document file_name'] === 'invoice.pdf'));
  const an = (await post('/api/studio/ask', q, { 'x-sg-as': 'analyst' })).body;
  assert.equal(an.count, 3); assert.ok(an.table.every(r => r['Document file_name'] === MASK)); assert.ok(an.masked.includes('Document file_name'));
  const s1 = await (await fetch(`${base}/api/studio/search?q=invoice`, { headers: { 'x-sg-as': 'analyst' } })).json();
  assert.equal(s1.results.length, 0, 'hidden document fields are not searchable');
  const csv = await (await fetch(`${base}/api/studio/export.csv`, { method: 'POST', headers: { 'content-type': 'application/json', 'x-sg-as': 'analyst' }, body: JSON.stringify(q) })).text();
  assert.ok(!csv.includes('invoice.pdf') && csv.includes(MASK), 'CSV export is masked too');
  await post('/api/studio/access/field', { entity: 'Document', field: 'file_name', sensitivity: 'low' });
  const an2 = (await post('/api/studio/ask', q, { 'x-sg-as': 'analyst' })).body;
  assert.ok(an2.table.some(r => r['Document file_name'] === 'invoice.pdf'));
  assert.ok(an2.table.every(r => r['Document sha256'] === MASK));
});

test('reset: documents, their things and uploaded files are cleared, and a new documents source works right after', async () => {
  assert.ok(S.app.graph.nodes('Document').length > 0);
  const r = await post('/api/studio/reset', { confirm: 'RESET' });
  assert.equal(r.status, 200);
  assert.deepEqual(S.app.graph.counts(), { nodes: 0, edges: 0 });
  assert.deepEqual(readdirSync(join(data, 'uploads')), [], 'uploaded documents are deleted');
  assert.equal(S.studio.workspace.sources.length, 0);
  await new Promise(res => setTimeout(res, 300));
  assert.deepEqual(S.app.graph.counts(), { nodes: 0, edges: 0 }, 'nothing comes back after the reset');
  const folder = (await (await fetch(`${base}/api/studio/upload?folder=w2&name=orders.csv`, { method: 'POST', body: readFileSync(join(FX, 'orders.csv')) })).json()).folder;
  assert.equal((await post('/api/studio/sources', { name: 'Again', kind: 'documents', settings: { folder }, tables: [] })).status, 200);
  assert.ok(await until(() => S.app.graph.nodes('Row').length === 2));
  assert.equal(S.app.graph.nodes('Row')[0].props.source_file, 'orders.csv');
});
